// 获取显示触摸板的硬件版本号 ------------------------------
void LCD_GetHardVer(void)
{
	CanTxBuf[0] = 0;
	CanTxBuf[1] = 0;
	CAN1_Send_Dat(250,2,CanTxBuf);
}

// 获取显示触摸板的软件版本号 ------------------------------
void LCD_GetSoftVer(void)
{
	CanTxBuf[0] = 0;
	CanTxBuf[1] = 0;
	CAN1_Send_Dat(251,2,CanTxBuf);
}

//清屏函数
//color:要清屏的填充色
void LCD_Clear(uint16_t color)
{
	//while(CanTx_BusyFlag);
	//CanTx_BusyFlag = 1;
	
	CanTxBuf[0] = (uint8_t)(color>>8);
	CanTxBuf[1] = (uint8_t)(color&0x00ff);
	
	CAN1_Send_Dat(10,2,CanTxBuf);
}

//清屏函数
//color:要清屏的填充色
//增加SVM+ERWEKA
void LCD_ClearSE(uint8_t mode, uint16_t color)
{
	//while(CanTx_BusyFlag);
	//CanTx_BusyFlag = 1;
	
	CanTxBuf[0] = (uint8_t)(color>>8);
	CanTxBuf[1] = (uint8_t)(color&0x00ff);
	
	CanTxBuf[2] = mode;
	
	CAN1_Send_Dat(11,3,CanTxBuf);
}

//在指定区域内填充单个颜色
//(sx,sy),(ex,ey):填充矩形对角坐标,区域大小为:(ex-sx+1)*(ey-sy+1)   
//color:要填充的颜色
void LCD_Fill(u16 sx,u16 sy,u16 ex,u16 ey,u16 color)
{
	//while(CanTx_BusyFlag);
	//CanTx_BusyFlag = 1;
	
	CanTxBuf[0] = (uint8_t)(sx>>8);
	CanTxBuf[1] = (uint8_t)(sx&0x00ff);
	CanTxBuf[2] = (uint8_t)(sy>>8);
	CanTxBuf[3] = (uint8_t)(sy&0x00ff);
	CanTxBuf[4] = (uint8_t)(ex>>8);
	CanTxBuf[5] = (uint8_t)(ex&0x00ff);
	CanTxBuf[6] = (uint8_t)(ey>>8);
	CanTxBuf[7] = (uint8_t)(ey&0x00ff);
	
	CanTxBuf[8] = (uint8_t)(color>>8);
	CanTxBuf[9] = (uint8_t)(color&0x00ff);
	
	CAN1_Send_Dat(20,10,CanTxBuf);
}

/*在指定位置显示一个图标
// x,y:起始坐标
// width,height:区域大小  
// *p:图标起始地址		  
// mode:叠加方式(1)还是非叠加方式(0)

//LCD_ShowIcon(50,400,64,64,WHITE,BLACK,31,0);  		// 黑线白底小房子
//LCD_ShowIcon(50,500,64,64,BLACK,WHITE,31,0); 			// 白线黑底小房子

//LCD_ShowIcon(120,400,48,48,WHITE,BLACK,32,0);  		// 黑线白底X
//LCD_ShowIcon(120,500,48,48,BLACK,WHITE,32,0);  		// 白线黑底X

//LCD_ShowIcon(176,400,32,24,BLACK,WHITE,33,0); 		// 黑线白底半表针
//LCD_ShowIcon(176,500,32,24,WHITE,BLACK,33,0); 		// 白线黑底半表针

//LCD_ShowIcon(235,400,16,32,BLACK,WHITE,34,0); 		// 黑线白底上下双箭头
//LCD_ShowIcon(235,500,16,32,WHITE,BLACK,34,0); 		// 白点黑底上下双箭头

//LCD_ShowIcon(32,30,64,48,WHITE,BLACK,9,0); 				// “三横”标*/

void LCD_ShowIcon(u16 x,u16 y,u16 width,u16 height,u16 pcolor,u16 bcolor,u8 p,u8 mode)
{
	//while(CanTx_BusyFlag);
	//CanTx_BusyFlag = 1;
	
	CanTxBuf[0] = (uint8_t)(x>>8);
	CanTxBuf[1] = (uint8_t)(x&0x00ff);
	CanTxBuf[2] = (uint8_t)(y>>8);
	CanTxBuf[3] = (uint8_t)(y&0x00ff);
	CanTxBuf[4] = (uint8_t)(width>>8);
	CanTxBuf[5] = (uint8_t)(width&0x00ff);
	CanTxBuf[6] = (uint8_t)(height>>8);
	CanTxBuf[7] = (uint8_t)(height&0x00ff);
	
	CanTxBuf[8] = (uint8_t)(pcolor>>8);
	CanTxBuf[9] = (uint8_t)(pcolor&0x00ff);
	CanTxBuf[10] = (uint8_t)(bcolor>>8);
	CanTxBuf[11] = (uint8_t)(bcolor&0x00ff);
	CanTxBuf[12] = mode;
	CanTxBuf[13] = p;
	
	CAN1_Send_Dat(30,14,CanTxBuf);
}

/*显示特殊字体字符串
// x,y:起点坐标
// width,height:区域大小  
// size:字体大小
// *p:字符串起始地址		  
// mode:叠加方式(1)还是非叠加方式(0)

// 文本对齐模式 ----------------------------
// 水平和垂直标记可以通过 “ OR”操作进行组合
// GUI_SetTextAlign(GUI_TA_HCENTER | GUI_TA_VCENTER);
// 水平对齐
// GUI_TA_LEFT X 轴方向左对齐 （默认）。
// GUI_TA_HCENTER X 轴方向居中。
// GUI_TA_RIGHT X 轴方向右对齐。
// 垂直对齐
// GUI_TA_TOP 在字符 Y 轴方向顶部对齐 （默认）。
// GUI_TA_VCENTER Y 轴方向居中。
// GUI_TA_BOTTOM 在字体 Y 轴底部像素线对齐。

// 文本绘制模式 ----------------------------
// 正常文本 GUI_TEXTMODE_NORMAL
// 反转文本 GUI_TEXTMODE_REV
// 透明文本 GUI_TEXTMODE_TRANS
// 异或文本 GUI_TEXTMODE_XOR
//GUI_SetTextMode(GUI_TM_TRANS);*/

void LCD_ShowSpStr(u16 x,u16 y,u16 width,u16 height,u16 pcolor,u16 bcolor,u8 size,char *p,u8 mode)
{
	u8 len;
	
	//while(CanTx_BusyFlag);
	//CanTx_BusyFlag = 1;
	
	CanTxBuf[0] = (uint8_t)(x>>8);
	CanTxBuf[1] = (uint8_t)(x&0x00ff);
	CanTxBuf[2] = (uint8_t)(y>>8);
	CanTxBuf[3] = (uint8_t)(y&0x00ff);
	CanTxBuf[4] = (uint8_t)(width>>8);
	CanTxBuf[5] = (uint8_t)(width&0x00ff);
	CanTxBuf[6] = (uint8_t)(height>>8);
	CanTxBuf[7] = (uint8_t)(height&0x00ff);
	
	CanTxBuf[8] = (uint8_t)(pcolor>>8);
	CanTxBuf[9] = (uint8_t)(pcolor&0x00ff);
	CanTxBuf[10] = (uint8_t)(bcolor>>8);
	CanTxBuf[11] = (uint8_t)(bcolor&0x00ff);
	CanTxBuf[12] = mode;
	CanTxBuf[13] = size;
	
	len = strlen(p);
	len += 14+1;
	strcpy(CanTxBuf+14,p);
	
	CAN1_Send_Dat(40,len,CanTxBuf);
}

/*显示数字,高位为0,则不显示
//x,y :起点坐标	 
//len :数字的位数
//size:字体大小
//color:颜色 
//num:数值(0~4294967295); */
void LCD_ShowSpNum(u16 x,u16 y,u16 pcolor,u16 bcolor,u32 num,u8 bitwidth,u8 size)
{
	//while(CanTx_BusyFlag);
	//CanTx_BusyFlag = 1;
	
	CanTxBuf[0] = (uint8_t)(x>>8);
	CanTxBuf[1] = (uint8_t)(x&0x00ff);
	CanTxBuf[2] = (uint8_t)(y>>8);
	CanTxBuf[3] = (uint8_t)(y&0x00ff);
	CanTxBuf[4] = (uint8_t)(pcolor>>8);
	CanTxBuf[5] = (uint8_t)(pcolor&0x00ff);
	CanTxBuf[6] = (uint8_t)(bcolor>>8);
	CanTxBuf[7] = (uint8_t)(bcolor&0x00ff);
	
	CanTxBuf[8] = bitwidth;
	CanTxBuf[9] = size;
	CanTxBuf[10] = 0;
	CanTxBuf[11] = 0;
	CanTxBuf[12] = (uint8_t)(num>>8);
	CanTxBuf[13] = (uint8_t)(num&0x00ff);
	
	CAN1_Send_Dat(50,14,CanTxBuf);
}

/*显示数字,高位为0,还是显示
//x,y:起点坐标
//num:数值(0~999999999);	 
//len:长度(即要显示的位数)
//size:字体大小
//mode:
//[7]:0,不填充;1,填充0.
//[6:1]:保留
//[0]:0,非叠加显示;1,叠加显示. */
void LCD_ShowxSpNum(u16 x,u16 y,u16 pcolor,u16 bcolor,u32 num,u8 bitwidth,u8 size,u8 mode)
{
	//while(CanTx_BusyFlag);
	//CanTx_BusyFlag = 1;
	
	CanTxBuf[0] = (uint8_t)(x>>8);
	CanTxBuf[1] = (uint8_t)(x&0x00ff);
	CanTxBuf[2] = (uint8_t)(y>>8);
	CanTxBuf[3] = (uint8_t)(y&0x00ff);
	CanTxBuf[4] = (uint8_t)(pcolor>>8);
	CanTxBuf[5] = (uint8_t)(pcolor&0x00ff);
	CanTxBuf[6] = (uint8_t)(bcolor>>8);
	CanTxBuf[7] = (uint8_t)(bcolor&0x00ff);
	
	CanTxBuf[8] = bitwidth;
	CanTxBuf[9] = size;
	CanTxBuf[10] = mode;
	
	CanTxBuf[11] = 0;
	CanTxBuf[12] = 0;
	CanTxBuf[13] = (uint8_t)(num>>8);
	CanTxBuf[14] = (uint8_t)(num&0x00ff);
	
	CAN1_Send_Dat(51,15,CanTxBuf);
}

